// Approved poster template and club logo.
export async function kartelaResponse(request) {
 const url=new URL(request.url);
    if (url.pathname === '/assets/areatza-logo-3d.webp') return new Response(Uint8Array.from(atob(''),c=>c.charCodeAt(0)), {headers:{'Content-Type':'image/webp','Cache-Control':'public, max-age=3600'}});
    if (url.pathname === '/api/kartela-template' && request.method === 'POST') {
      let pin; try { pin=(await request.json()).pin; } catch { return new Response('PIN baliogabea', {status:400}); }
      if(pin!=='0000')return new Response('PIN okerra', {status:403});
      return new Response(Uint8Array.from(atob(''), c=>c.charCodeAt(0)), {headers:{'Content-Type':'image/jpeg','Cache-Control':'no-store'}});
    }

 return null;
}
